import{_ as t,o as e,c as s,a3 as o}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart.md","filePath":"quickstart.md","lastUpdated":1791133906000}'),r={name:"quickstart.md"};function d(i,a,l,n,c,p){return e(),s("div",null,[...a[0]||(a[0]=[o('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>本篇带你从零装好，并完成第一次「改数值 → 看到效果」。全程在手机上完成，不需要连电脑。</p><h2 id="三步走" tabindex="-1">三步走 <a class="header-anchor" href="#三步走" aria-label="Permalink to &quot;三步走&quot;">​</a></h2><h3 id="第一步-安装-带-mod-框架的版本" tabindex="-1">第一步：安装 带 Mod 框架的版本 <a class="header-anchor" href="#第一步-安装-带-mod-框架的版本" aria-label="Permalink to &quot;第一步：安装 带 Mod 框架的版本&quot;">​</a></h3><p>下载试装包，装到安卓手机上：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>final_full_cn_MOD_v1.apk</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">装之前先备份存档</p><p>框架本身不会破坏存档，但<strong>任何改动游戏的做法都建议先备份</strong>。存档在手机的：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Android/data/&lt;游戏包名&gt;/files/rncampaignInfo.dat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>把它复制出来一份放着就行。</p></div><p>详细安装步骤（含「未知来源」权限、覆盖安装、空间不足的处理）见 <a href="/AtlanticFleetSite/docs/deploy/android">安卓手机安装</a>。</p><h3 id="第二步-启动游戏-找到「小u」" tabindex="-1">第二步：启动游戏，找到「小u」 <a class="header-anchor" href="#第二步-启动游戏-找到「小u」" aria-label="Permalink to &quot;第二步：启动游戏，找到「小u」&quot;">​</a></h3><p>进游戏后，屏幕边缘会出现一个半透明的圆形悬浮窗，上面写着「<strong>u</strong>」。这就是控制台入口。</p><ul><li><strong>点一下</strong>它，打开控制台面板。</li><li>如果没看到，试试<strong>三根手指同时按屏幕</strong>（这是强制唤起的兜底手势）。</li><li>面板默认停在「<strong>帮助</strong>」页，那里有每个页面的说明。</li></ul><p>还不熟悉怎么操作？看 <a href="/AtlanticFleetSite/docs/use/gestures">悬浮窗操作技巧</a>。</p><h3 id="第三步-改一个参数-看效果" tabindex="-1">第三步：改一个参数，看效果 <a class="header-anchor" href="#第三步-改一个参数-看效果" aria-label="Permalink to &quot;第三步：改一个参数，看效果&quot;">​</a></h3><ol><li>点悬浮窗打开面板 → 切到「<strong>参数</strong>」页。</li><li>找到「<strong>战斗 → 主炮伤害</strong>」这一组，拖动滑块，把它从 <code>1.0</code> 调到 <code>1.5</code>。</li><li>关掉面板，<strong>完全退出游戏再重开</strong>（参数在启动时读取）。</li><li>进一场战斗，开一炮 —— 伤害明显变高了。</li></ol><p>恭喜，你已经完成第一次 Mod。</p><div class="tip custom-block"><p class="custom-block-title">想立刻看到「偏离原版」的清单？</p><p>面板 → 「<strong>状态</strong>」页，那里会列出所有<strong>被你改过、且当前值不等于原版默认值</strong>的参数，一眼看全你动过什么。这是排查「我怎么感觉数值不对」最快的地方。</p></div><h2 id="三种上手路径" tabindex="-1">三种上手路径 <a class="header-anchor" href="#三种上手路径" aria-label="Permalink to &quot;三种上手路径&quot;">​</a></h2><p>刚接触这个框架，按你的目标选一条路走：</p><table tabindex="0"><thead><tr><th>你的目标</th><th>走这条路</th></tr></thead><tbody><tr><td>只想把数值调爽</td><td><a href="/AtlanticFleetSite/docs/use/params-page">参数页：调数值</a> → <a href="/AtlanticFleetSite/docs/features/params">参数系统</a></td></tr><tr><td>想装别人做的 Mod</td><td><a href="/AtlanticFleetSite/docs/deploy/install-mod">安装 Mod 的三种方式</a> → <a href="/AtlanticFleetSite/docs/use/mods-page">Mod 页</a></td></tr><tr><td>想自己做 Mod</td><td><a href="/AtlanticFleetSite/docs/dev/mod-json">mod.json 完整规范</a> → <a href="/AtlanticFleetSite/docs/dev/publish">发布到仓库</a></td></tr><tr><td>想加自己的船 / 模型</td><td><a href="/AtlanticFleetSite/docs/features/ships">自定义舰船</a> → <a href="/AtlanticFleetSite/docs/features/models">自制模型</a></td></tr><tr><td>玩出问题了</td><td><a href="/AtlanticFleetSite/docs/use/troubleshooting">出问题了怎么查</a> → <a href="/AtlanticFleetSite/docs/use/log-page">日志页</a></td></tr></tbody></table><h2 id="三个最常用的操作" tabindex="-1">三个最常用的操作 <a class="header-anchor" href="#三个最常用的操作" aria-label="Permalink to &quot;三个最常用的操作&quot;">​</a></h2><p><strong>① 调数值</strong> 「参数」页 → 拖滑块 → 重开游戏生效。倍率类默认 <code>1.0</code>，开关类默认 <code>0</code>。</p><p><strong>② 装别人的 Mod</strong> 「参数」页 →「粘贴导入分享码」→ 粘贴一串 <code>AFMOD1:…</code> → 自动落盘 → 重开游戏。</p><p><strong>③ 自查问题</strong> 「日志」页 → 按「告警」「错误」筛选 → 点「复制全部日志」→ 发给作者。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想了解框架的能力边界 → <a href="/AtlanticFleetSite/docs/features/start">功能接入总览</a></li><li>想搞懂六个页面各干什么 → <a href="/AtlanticFleetSite/docs/use/panel">游戏内控制台「小u」</a></li><li>想自己做 Mod 给别人用 → <a href="/AtlanticFleetSite/docs/dev/start">开发总览</a></li></ul>',25)])])}const g=t(r,[["render",d]]);export{u as __pageData,g as default};
